import csv

def total_csv_prices(path):
    total = 0
    with open(path, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f, strict=True)
        try:
            names = reader.fieldnames or []
            if len(names) != len(set(names)) or set(names) != {"id", "price"}:
                raise ValueError
            for row in reader:
                line = reader.line_num
                if None in row or not row["id"] or not row["id"].strip():
                    raise ValueError(line)
                try:
                    total += int(row["price"])
                except (TypeError, ValueError) as exc:
                    raise ValueError(line) from exc
        except csv.Error as exc:
            raise ValueError(reader.reader.line_num) from exc
    return total

