import csv

def read_records(path):
    with open(path, encoding="utf-8", newline="") as f:
        reader = csv.DictReader(f, strict=True)
        try:
            names = reader.fieldnames or []
            if len(names) != len(set(names)) or set(names) != {"name", "amount"}:
                raise ValueError(max(1, reader.line_num))
            records = []
            for row in reader:
                line = reader.line_num
                if None in row or row["name"] is None or row["amount"] is None:
                    raise ValueError(line)
                try:
                    records.append(normalize_record(row))
                except ValueError as exc:
                    raise ValueError(line) from exc
            return records
        except csv.Error as exc:
            raise ValueError(reader.reader.line_num) from exc

