static bool parse_port(const char *text, uint16_t *out)
{
    if (!text || !out || !*text) return false;
    for (const unsigned char *p = (const unsigned char *)text;
         *p; ++p) if (*p < '0' || *p > '9') return false;
    errno = 0;
    char *end;
    unsigned long v = strtoul(text, &end, 10);
    if (errno == ERANGE || *end || v > UINT16_MAX)
        return false;
    *out = (uint16_t)v;
    return true;
}

