static bool append_bytes(struct Buffer *b,
                         const void *src, size_t n)
{
    if (n == 0) return true;
    if (src == NULL) return false;
    size_t needed;
    if (!checked_add_size(b->size, n, &needed) ||
        !buffer_reserve(b, needed)) return false;
    memcpy(b->data + b->size, src, n);
    b->size = needed;
    return true;
}

static bool append_cstr(struct Buffer *b, const char *s)
{
    size_t len = strlen(s);
    return append_bytes(b, s, len);
}

static bool reserve_for_append(struct Buffer *b, size_t extra)
{
    size_t needed;
    if (!checked_add_size(b->size, extra, &needed)) return false;
    if (needed <= b->capacity) return true;
    size_t cap = b->capacity ? b->capacity : 64;
    while (cap < needed) {
        if (cap > SIZE_MAX / 2) { cap = needed; break; }
        cap *= 2;
    }
    return buffer_reserve(b, cap);
}

static bool read_stdin_line(char *buf, size_t cap)
{
    if (!buf || cap < 2 || cap > INT_MAX) return false;
    if (!fgets(buf, (int)cap, stdin)) return false;
    size_t len = strlen(buf);
    if (len && buf[len - 1] == '\n') {
        buf[len - 1] = '\0';
        return true;
    }
    int ch = getchar();
    if (ch == EOF) return !ferror(stdin);
    if (ch == '\n') return true;
    while (ch != '\n' && ch != EOF) ch = getchar();
    return false;
}

static bool process_text_lines(FILE *fp)
