            if (ch != EOF && ch != '\n') return false;
            if (ferror(fp)) return false;
        }
        if (!handle_line(line)) return false;
    }
    return !ferror(fp);
}

static bool read_token(FILE *fp, char *buf, size_t cap)
{
    if (!fp || !buf || cap < 256) return false;
    if (fscanf(fp, "%255s", buf) != 1) return false;
    int ch = fgetc(fp);
    if (ch == EOF) return !ferror(fp);
    if (isspace((unsigned char)ch)) return true;
    do {
        ch = fgetc(fp);
    } while (ch != EOF && !isspace((unsigned char)ch));
    return false;
}

static bool read_entire_file(FILE *fp, unsigned char **out,
                             size_t *out_size)
{
    struct Buffer b = {0};
    unsigned char chunk[4096];
    size_t n;
    while ((n = fread(chunk, 1, sizeof chunk, fp)) != 0) {
        if (!append_bytes(&b, chunk, n)) {
            destroy_buffer(&b);
            return false;
        }
    }
    if (ferror(fp)) {
        destroy_buffer(&b);
        return false;
    }
    *out = b.data;
    *out_size = b.size;
    return true;
}

static bool copy_stream_and_flush(FILE *in, FILE *out)
{
    unsigned char buf[4096];
    size_t n;
    while ((n = fread(buf, 1, sizeof buf, in)) != 0) {
        if (fwrite(buf, 1, n, out) != n) return false;
    }
    if (ferror(in)) return false;
    return fflush(out) == 0;
}

