enum ReadLineResult {
    LINE_OK,
    LINE_EOF,
    LINE_TOO_LONG,
    LINE_INVALID,
    LINE_IO_ERROR
};

static enum ReadLineResult read_line(FILE *fp, char *buf, size_t cap)
{
    if (!fp || !buf || cap < 2) return LINE_INVALID;
    size_t n = 0;
    int ch;
    while ((ch = fgetc(fp)) != EOF) {
        if (ch == '\n') { buf[n] = '\0'; return LINE_OK; }
        if (ch == '\0' || (unsigned)ch > 127u) return LINE_INVALID;
        if (n >= cap - 1) return LINE_TOO_LONG;
        buf[n++] = (char)ch;
    }
    if (ferror(fp)) return LINE_IO_ERROR;
    if (n == 0) return LINE_EOF;
    buf[n] = '\0'; return LINE_OK;
}

for (;;) {
    char line[256];
    enum ReadLineResult r = read_line(fp, line, sizeof line);
    if (r == LINE_EOF) return true;
    if (r != LINE_OK || !consume(line)) return false;
}

bool parse_int_line(const char *text, int *out)
{
    if (!text || !out || !*text) return false;
    const char *p = text;
    if (*p == '+' || *p == '-') ++p;
    if (!*p) return false;
    for (; *p; ++p) if (*p < '0' || *p > '9') return false;
    errno = 0;
    char *end;
    long v = strtol(text, &end, 10);
    if (errno == ERANGE || *end || v < INT_MIN || v > INT_MAX) return false;
    *out = (int)v;
    return true;
}

