bool process_stream(FILE *fp, struct Stats *out)
{
    if (!fp || !out) return false;
    struct Stats temp = {0};
    char line[256];
    for (;;) {
        enum ReadLineResult r = read_line(fp, line, sizeof line);
        if (r == LINE_EOF) break;
        if (r != LINE_OK) return false;
        int value;
        if (!parse_int_line(line, &value) || !stats_add(&temp, value)) return false;
    }
    *out = temp;
    return true;
}

static bool run_file(const char *path, struct Stats *out)
{
    if (!path || !out) return false;
    FILE *fp = fopen(path, "rb");
    if (!fp) return false;
    struct Stats temp;
    bool ok = process_stream(fp, &temp);
    if (fclose(fp) == EOF) ok = false;
    if (ok) *out = temp;
    return ok;
}

bool print_stats(const struct Stats *s)
{
    if (!s) return false;
    if (printf("count=%zu\nsum=%lld\n", s->count, s->sum) < 0)
        return false;
    if (s->count == 0) return true;
    return printf("min=%d\nmax=%d\n", s->minimum, s->maximum) >= 0;
}

