    if (!run_file(argv[1], &stats)) {
        fputs("failed to process input\n", stderr);
        return EXIT_FAILURE;
    }
    if (!print_stats(&stats) || fflush(stdout) == EOF) return EXIT_FAILURE;
    return EXIT_SUCCESS;
}

