def median_stable(nums):
    if not nums:
        raise ValueError
    data = sorted(nums)
    mid = len(data) // 2
    if len(data) % 2:
        return data[mid]
    left, right = data[mid - 1], data[mid]
    if left < 0 < right or (abs(left) < 1 and abs(right) < 1):
        return (left + right) / 2
    return left + (right - left) / 2

