from collections import deque
from math import fsum

def moving_average_iterable(values, window):
    if type(window) is not int or window <= 0:
        raise ValueError
    queue = deque(maxlen=window)
    result = []
    for value in values:
        queue.append(value)
        if len(queue) == window:
            result.append(fsum(queue) / window)
    return result

