_MISSING = object()

def changed_fields(before, after):
    result = []
    keys = dict.fromkeys([*before, *after])
    for key in keys:
        old = before.get(key, _MISSING)
        new = after.get(key, _MISSING)
        if old != new:
            result.append((key, old, new))
    return result

