static bool take_byte(const unsigned char **cursor,
                      size_t *remaining, unsigned char *out)
{
    if (!cursor || !remaining || !out || *remaining == 0)
        return false;
    if (*cursor == NULL) return false;
    unsigned char v = **cursor;
    ++*cursor;
    --*remaining;
    *out = v;
    return true;
}

static bool take_bytes(const unsigned char **cursor, size_t *remaining,
                       size_t n, const unsigned char **out)
{
    if (cursor == out || n > *remaining) return false;
    *out = *cursor;
    if (n != 0) *cursor += n;
    *remaining -= n;
    return true;
}

static bool cursor_skip(struct Cursor *c, size_t n)
{
    if (n > c->remaining) return false;
    c->ptr += n;
    c->remaining -= n;
    return true;
}

static bool cursor_read_be16(struct Cursor *c, uint16_t *out)
{
    if (!c || !out || c->remaining < 2 || !c->ptr) return false;
    uint16_t v = read_be16(c->ptr);
    c->ptr += 2;
    c->remaining -= 2;
    *out = v;
