static bool read_entire_file(FILE *fp, unsigned char **out,
                             size_t *out_size)
{
    struct Buffer b = {0};
    unsigned char chunk[4096];
    size_t n;
    while ((n = fread(chunk, 1, sizeof chunk, fp)) != 0) {
        if (!append_bytes(&b, chunk, n)) {
            destroy_buffer(&b);
            return false;
        }
    }
    if (ferror(fp)) {
        destroy_buffer(&b);
        return false;
    }
    *out = b.data;
    *out_size = b.size;
    return true;
}

static bool copy_stream_and_flush(FILE *in, FILE *out)
{
    unsigned char buf[4096];
    size_t n;
    while ((n = fread(buf, 1, sizeof buf, in)) != 0) {
        if (fwrite(buf, 1, n, out) != n) return false;
    }
    if (ferror(in)) return false;
    return fflush(out) == 0;
}

static bool load_numbers(FILE *fp, struct IntVector *out)
{
    char line[128];
    while (fgets(line, sizeof line, fp)) {
        size_t len = strlen(line);
        if (len == 0 || line[len - 1] != '\n') return false;
        line[len - 1] = '\0';
        int value;
        if (!parse_decimal_int_line(line, &value)) return false;
        if (!vector_push(out, value)) return false;
    }
    return !ferror(fp);
}

static bool load_config_line(char *line, struct Config *cfg)
{
    char *key;
    char *value;
