bool stats_add(struct Stats *s, int value)
{
    if (!s || s->count == SIZE_MAX) return false;
    long long x = value;
    if (x > 0 && s->sum > LLONG_MAX - x) return false;
    if (x < 0 && s->sum < LLONG_MIN - x) return false;
    struct Stats next = *s;
    if (next.count == 0 || value < next.minimum) next.minimum = value;
    if (next.count == 0 || value > next.maximum) next.maximum = value;
    next.sum += x;
    ++next.count;
    *s = next;
    return true;
}

